        sb.append("by level: DEBUG=").append(debugCount)
                .append(" INFO=").append(infoCount)
                .append(" WARN=").append(warnCount)
                .append(" ERROR=").append(errorCount).append("\n");
        sb.append("first: ").append(first == null ? "n/a" : first).append("\n");
        sb.append("last: ").append(last == null ? "n/a" : last).append("\n");
        sb.append("top errors:\n");
        int limit = Math.min(top, sortedGroups.size());
        for (int i = 0; i < limit; i++) {
            Group g = sortedGroups.get(i);
            sb.append("  ").append(g.count).append(" ").append(g.message).append("\n");
        }

        System.out.print(sb);
        System.out.flush();
    }

    private static String normalize(String message) {
        String s = message;
        s = UUID_PATTERN.matcher(s).replaceAll("<uuid>");
        s = HEX_PATTERN.matcher(s).replaceAll("<hex>");
        s = DIGIT_PATTERN.matcher(s).replaceAll("<num>");
        return s;
    }

    private static void printHelp() {
        StringBuilder sb = new StringBuilder();
        sb.append("Usage: logsum [FILE] [--since TIMESTAMP] [--level LEVEL] [--top N]\n");
        sb.append("\n");
        sb.append("Streaming summary of a log file (or stdin).\n");
        sb.append("\n");
        sb.append("Arguments:\n");
        sb.append("  FILE             log file to read; omitted or - means stdin\n");
        sb.append("\n");
        sb.append("Options:\n");
        sb.append("  --since TIMESTAMP  only consider lines with TIMESTAMP >= this value\n");
        sb.append("  --level LEVEL      only consider lines at exactly this level\n");
        sb.append("  --top N            number of top error groups to show (default 5)\n");
        sb.append("  --help             show this help and exit\n");
        System.out.print(sb);
        System.out.flush();
    }

    private static void usageError(String message) {
        System.err.println("error: " + message);
        System.exit(2);
    }

    private static void errorExit(String message) {
        System.err.println("error: " + message);
        System.exit(2);
    }

    private static class Group {
        final String message;
        long count;

        Group(String message) {
            this.message = message;
            this.count = 0;
        }
    }
}

